import sys
import os
import json
import re
from collections import defaultdict

FIELD_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def format_date(val):
    if not val:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    m = re.match(r"^(\d{4})[/-](\d{1,2})[/-](\d{1,2})$", val)
    if m:
        return f"{m.group(1)}-{int(m.group(2)):02d}-{int(m.group(3)):02d}"
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    enforcement_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    by_recall_number = defaultdict(list)

    if os.path.exists(enforcement_path):
        with open(enforcement_path, "r", encoding="utf-8") as f:
            data = json.load(f)
        items = data.get("results", data) if isinstance(data, dict) else data
        if isinstance(items, list):
            for item in items:
                rec_num = item.get("recall_number")
                if rec_num:
                    by_recall_number[rec_num.strip()].append(item)

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        fact_names = facts_schema.get(rule_id, [])

        records = by_recall_number.get(entity, [])
        pair_result = {}

        for fact_name in fact_names:
            if fact_name not in FIELD_MAP:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = FIELD_MAP[fact_name]
            values = set()

            for record in records:
                raw_val = record.get(field_name)
                formatted = format_date(raw_val)
                if formatted is not None:
                    values.add(formatted)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [next(iter(values)), doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

