import sys
import os
import json

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() in ("N/A", "NONE", "UNKNOWN"):
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    return val

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    # Load fda_enforcement_reports
    fda_file_candidates = [
        os.path.join(packet_dir, "fda_enforcement_reports.json"),
        os.path.join(packet_dir, "fda_enforcement_reports")
    ]
    fda_data = []
    doc_name = "fda_enforcement_reports"

    for candidate in fda_file_candidates:
        if os.path.exists(candidate):
            with open(candidate, "r", encoding="utf-8") as f:
                content = json.load(f)
                if isinstance(content, dict):
                    fda_data = content.get("results", [])
                elif isinstance(content, list):
                    fda_data = content
            break

    # Index records by recall_number
    records_by_entity = {}
    for item in fda_data:
        recall_num = item.get("recall_number")
        if recall_num:
            recall_num_str = str(recall_num).strip()
            records_by_entity.setdefault(recall_num_str, []).append(item)

    field_map = {
        "initiation date": "recall_initiation_date",
        "classification date": "center_classification_date",
        "termination date": "termination_date"
    }

    results = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        needed_facts = facts_schema.get(rule_id, [])
        pair_result = {}

        entity_records = records_by_entity.get(entity, [])

        for fact in needed_facts:
            field_name = field_map.get(fact)
            if not field_name:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for rec in entity_records:
                raw_val = rec.get(field_name)
                formatted_val = parse_date(raw_val)
                if formatted_val is not None:
                    values.add(formatted_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [list(values)[0], doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        results[pair] = pair_result

    print(json.dumps(results, indent=2))

if __name__ == "__main__":
    main()

