import sys
import os
import json
import re

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    m = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", val)
    if m:
        return val
    return val

FACT_MAPPING = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date", parse_date),
    "classification date": ("fda_enforcement_reports", "center_classification_date", parse_date),
    "termination date": ("fda_enforcement_reports", "termination_date", parse_date),
}

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    fda_file_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    fda_records = []
    if os.path.exists(fda_file_path):
        with open(fda_file_path, "r", encoding="utf-8") as f:
            data = json.load(f)
            fda_records = data.get("results", [])

    # Index fda records by recall_number
    records_by_recall = {}
    for r in fda_records:
        rec_num = r.get("recall_number")
        if rec_num:
            records_by_recall.setdefault(str(rec_num).strip(), []).append(r)

    output = {}

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        entity_key = entity.strip()

        pair_result = {}
        fact_names = facts_by_rule.get(rule_id, [])

        matching_records = records_by_recall.get(entity_key, [])

        for fact_name in fact_names:
            if fact_name in FACT_MAPPING:
                doc_name, field_name, transform = FACT_MAPPING[fact_name]
                values = []
                for rec in matching_records:
                    raw_val = rec.get(field_name)
                    parsed = transform(raw_val) if transform else raw_val
                    if parsed is not None and parsed != "":
                        if parsed not in values:
                            values.append(parsed)

                if len(values) == 0:
                    pair_result[fact_name] = "ABSENT"
                elif len(values) == 1:
                    pair_result[fact_name] = [values[0], doc_name]
                else:
                    pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = "ABSENT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

