import sys
import os
import json

FACT_MAPPING = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def normalize_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
    if len(val) == 10 and val[4] == '-' and val[7] == '-':
        return val
    return val

def load_data(packet_dir):
    data_cache = {}
    reports_path = os.path.join(packet_dir, "fda_enforcement_reports.json")
    if os.path.exists(reports_path):
        with open(reports_path, "r", encoding="utf-8") as f:
            raw = json.load(f)
            if isinstance(raw, dict) and "results" in raw:
                data_cache["fda_enforcement_reports"] = raw["results"]
            elif isinstance(raw, list):
                data_cache["fda_enforcement_reports"] = raw
            else:
                data_cache["fda_enforcement_reports"] = []
    else:
        data_cache["fda_enforcement_reports"] = []
    return data_cache

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    data_cache = load_data(packet_dir)

    # Index fda_enforcement_reports by recall_number
    reports_by_recall = {}
    for record in data_cache.get("fda_enforcement_reports", []):
        recall_num = record.get("recall_number")
        if recall_num:
            reports_by_recall.setdefault(recall_num.strip(), []).append(record)

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity = entity.strip()
        expected_facts = facts_schema.get(rule_id, [])

        pair_result = {}
        matching_records = reports_by_recall.get(entity, [])

        for fact_name in expected_facts:
            if fact_name not in FACT_MAPPING:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name = FACT_MAPPING[fact_name]

            values = set()
            for rec in matching_records:
                raw_val = rec.get(field_name)
                norm_val = normalize_date(raw_val)
                if norm_val is not None:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [list(values)[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()

